-- Promptzyra: exactly 20 original starter blog articles with replaceable placeholder images. Review content before publishing.
-- Run in Supabase SQL Editor for the Promptzyra project only.
-- Requires public.promptzyra_posts schema described in SETUP.md.
ON CONFLICT (slug) DO UPDATE SET published = true, thumbnail = EXCLUDED.thumbnail, image1 = EXCLUDED.image1, image2 = EXCLUDED.image2;
